    Sell:{routes:['valuation','sold','seller-guide','staging','home-improvements'],img:'henderson.jpg?v=2',ctas:[['Get my home value','valuation'],['See past sales','sold'],['Seller resources','seller-guide'],['Home staging','staging']]},
