    return `<article class="studio-property ${compact?'is-compact':''}"><button class="studio-property-img" data-property="${h.id}" aria-label="View ${esc(h.name)}"><img src="${esc(h.image)}" alt="Architectural illustration of ${esc(h.name)}" loading="lazy">${badges(h)}</button><button class="studio-heart ${saved?'active':''}" type="button" data-fave="${h.id}" aria-pressed="${saved}" aria-label="${saved?'Remove saved home':'Save home'}">${saved?'♥':'♡'}</button><div class="studio-property-body"><span class="studio-img-tag label-outside-photo">${esc(h.tag)}</span><span class="micro-label">${esc(h.city)} · ${esc(h.type||'HOME')}</span><h3>${esc(h.name)}</h3><strong class="studio-home-price">${usd(h.price)}</strong><div class="studio-home-stats"><span>${h.beds} BEDS</span><span>${h.baths} BATHS</span><span>${Number(h.sqft).toLocaleString()} SQ FT</span></div><span class="studio-mls">LISTING # ${esc(h.reference)}${h.subdivision?` · ${esc(h.subdivision)}`:''}${h.soldDate?` · SOLD ${esc(h.soldDate)}`:''}</span><button class="studio-card-link" data-property="${h.id}">EXPLORE PROPERTY <span>↗</span></button></div></article>`;
