  function nextDays(n){const out=[],d=new Date();for(let i=1;i<=n;i++){const x=new Date(d.getFullYear(),d.getMonth(),d.getDate()+i);out.push({value:x.toISOString().slice(0,10),label:x.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})});}return out;}
