     <div class="pd-actionbar"><button class="studio-btn" data-action="pd-mode" data-mode="tour">Schedule tour</button><button class="studio-btn secondary" data-action="pd-mode" data-mode="info">Request info</button><button class="studio-btn secondary" data-action="share" data-id="${h.id}">Share</button><button class="studio-btn secondary" data-fave="${h.id}">${saved?'♥ Saved':'♡ Save'}</button>${h.virtualTour?'<button class="studio-btn secondary" data-action="virtual-tour">▶ Virtual tour</button>':''}</div>
