      <section><h2>Map</h2><div class="pd-map"><span class="map-neighborhood n1">NORTH LAS VEGAS</span><span class="map-neighborhood n2">LAS VEGAS</span><span class="map-neighborhood n3">HENDERSON</span><span class="map-neighborhood n4">BOULDER CITY</span><i class="pd-pin" style="left:${h.coords?.[0]||50}%;top:${h.coords?.[1]||50}%"><b>${esc(h.name)}</b></i></div><div class="studio-actions"><button class="studio-btn secondary" data-go="map">Open map search ↗</button><button class="studio-btn secondary" data-community="${esc(h.city)}">${esc(h.city)} community guide ↗</button></div><p class="studio-form-note">Conceptual map. Pin position does not represent a real address.</p></section>
