  function calcPd(){const f=$('#studioPdCalc');if(!f)return;const d=Object.fromEntries(new FormData(f)),p=Number(d.price)||0,loan=p*(1-(Number(d.down)||0)/100),r=(Number(d.rate)||0)/1200,n=Number(d.years)*12,pi=r?loan*r/(1-Math.pow(1+r,-n)):loan/n,tax=p*.0065/12,ins=200,h=findHome(state.params.id),hoa=h?.hoa||0;
    $('#pdCalcTotal').textContent=usd(Math.round(pi+tax+ins+hoa))+' / mo';$('#pdCalcParts').textContent=`Principal & interest ${usd(Math.round(pi))} · Taxes ~${usd(Math.round(tax))} · Insurance ~${usd(ins)} · HOA ${usd(hoa)}. Estimate only.`;}
