      <fieldset class="valuation-options"><legend>Bathrooms</legend>${[1,2,3,4,'5+'].map((x,i)=>`<label><input type="radio" name="bathrooms" value="${x}" ${i===0?'checked':''}> ${x}</label>`).join('')}</fieldset>
